VEHICLE_ROUTES: dict[int, list[list[float]]] = {
    101: ROUTE_101,
    102: ROUTE_102,
    103: ROUTE_103,
}

def _distance_sq(p1: list[float], p2: list[float]) -> float:
    return (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2

def get_next_road_location(veiculo_id: int, current_lon: float, current_lat: float, step: int = 3) -> list[float]:
    """Retorna o próximo ponto na via pública para o veículo especificado."""
    route = VEHICLE_ROUTES.get(veiculo_id, ROUTE_101)
    # Cria trajeto de ida e volta (round-trip) na mesma via
    full_path = route + route[-2:0:-1]
    
    # Encontra o ponto mais próximo no trajeto
    closest_idx = 0
    min_dist = float('inf')
    for idx, pt in enumerate(full_path):
        dist = _distance_sq([current_lon, current_lat], pt)
        if dist < min_dist:
            min_dist = dist
            closest_idx = idx
            
    # Avança no trajeto
    next_idx = (closest_idx + step) % len(full_path)
    return full_path[next_idx]
